    // Cancel any existing animation loop
    if (loopId !== null) {
      cancelAnimationFrame(loopId);
      loopId = null;
    }
    // Reset game state
    ship = { x: W/2, y: H/2, vx: 0, vy: 0, angle: 0, alive: true };
    bullets = [];
    obstacles = [];
    split = false;
    laneShift = 0;
    score = 0;
    phase = 'playing';
    keys = new Set();
    lastTime = performance.now();
    publishState();
    startLoop();
  }

